node <<'NODE'
const assert = require('node:assert/strict');
const fs = require('node:fs');
const handoff = fs.readFileSync('HANDOFF.md', 'utf8');
const links = Array.from(handoff.matchAll(/\]\(([^)#]+)#L(\d+)\)/g));
assert.ok(links.length > 0);
for (const [, path, line] of links) {
    assert.ok(path.startsWith('vendure/'));
    const sourceLine = fs.readFileSync(path, 'utf8').split('\n')[Number(line) - 1];
    assert.ok(sourceLine?.trim(), path + '#' + line);
}
console.log('Verified ' + links.length + ' relative source links.');
console.log(fs.readdirSync('.').sort().join('\n'));
NODE
